// Convierte la respuesta de HA (o su ausencia) en un 1 o un 0.
//
// Este nodo existe porque HA NO PUEDE decir que esta caido: para contestar `up: 0`
// tendria que estar vivo. Cuando el Green cae no llega un cero, no llega NADA, y ese
// silencio es justo la senal. Aqui es donde se convierte en un campo.
//
// Sale SIEMPRE un item, para que el IF de detras sea legible y para que la ejecucion
// deje rastro tambien cuando todo va bien.

const j    = $input.first().json;
const hoy  = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Madrid' });

let ok = 1, estado = 'ok', detalle = '';

if (j.error) {
  const txt = String(j.error.message ?? j.error);

  // 401 y "no contesta" NO son el mismo problema, aunque los dos rompan el sondeo.
  // Un token revocado con el Green perfectamente vivo daria un "HA caido" falso, y a
  // las 3 de la manana la diferencia entre ir a mirar la casa y renovar una credencial
  // por la manana es toda la diferencia.
  if (/401|unauthor/i.test(txt)) {
    ok = 0; estado = 'token';
    detalle = 'El token de Home Assistant ya no vale (401). El Green puede estar perfectamente: lo que hay que renovar es la credencial de n8n.';
  } else {
    ok = 0; estado = 'caido';
    detalle = ('El Green no contesta: ' + txt).slice(0, 200);
  }

} else if (j.state && j.state !== 'RUNNING') {
  // El `j.state &&` no sobra: si una version de HA dejara de devolver ese campo, sin el
  // la condicion seria cierta SIEMPRE y esto avisaria cada 5 minutos para siempre.
  // Ante la duda, callar: para "no contesta" ya esta la rama de arriba.
  ok = 0; estado = 'arrancando';
  detalle = 'Home Assistant contesta pero su estado es "' + j.state + '", no RUNNING.';
}

return [{ json: {
  ok,
  estado,
  detalle,
  version: j.version ?? null,
  // La fecha va DENTRO del nombre porque el backend deduplica por `huella=workflow`
  // durante AVISOS_REPETIR_DIAS (5). Sin ella, una caida el lunes taparia la del
  // jueves. Con ella: como mucho un aviso al dia, y nunca cinco dias de silencio.
  workflow: 'vigilante-green (' + hoy + ')',
} }];
